"""Audit all retained original single/multi overlap tables under the explicit active-entry contract before runtime regression."""
import argparse,json,os,subprocess
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from validate_mashr_native import JAVA21


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--build',required=True,type=Path);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();base=ROOT/'build/literature-review/smr-runtime';assert out.is_relative_to(base) and not out.exists();out.mkdir(parents=True);build=json.loads((a.build/'COMPLETED.json').read_bytes());jar=ROOT/build['artifact']['path'];assert pin(jar)=={k:build['artifact'][k] for k in ['bytes','sha256']};pins={n:pin(ROOT/n) for n in [*build['source_pins'],Path(__file__).resolve().relative_to(ROOT).as_posix()]};assert all(pins[n]==v for n,v in build['source_pins'].items());runner=out/'SmrOverlapContract.java';runner.write_text('''package org.jlinalg.cli;import java.nio.file.*;import java.util.*;import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
public final class SmrOverlapContract{public static void main(String[] args)throws Exception{Path old=Path.of(args[0]),out=Path.of(args[1]);var m=object(NextflowParameters.parse(Files.readString(old.resolve("request.json")),1048576,100000));var cases=new ArrayList<Map<String,Object>>();for(Object value:list(m.get("analyses"))){var a=object(value);if(a.get("kind").equals("multi"))a.put("sample_overlap",Map.of("kind","source-flag-without-estimation"));cases.add(a);}m.put("analyses",cases);var r=SmrWorkflowRequest.parse(m,old);var b=new SmrWorkflowInputs.Budget(r.nativeOperations());Path inputs=old.resolve("analysis/inputs");var g=SmrWorkflowInputs.gwas(inputs.resolve("gwas.ma"),r,b);var q=SmrWorkflowBesd.read(old.resolve("analysis/worker/prepare/original"),r,b);var population=SmrWorkflowInputs.population(inputs,q,g,r,b);for(var a:r.analyses()){String id=text(a.get("id"));Path from=old.resolve("analysis/worker/cases").resolve(id),home=Files.createDirectory(out.resolve(id));try(var files=Files.list(from)){for(Path file:files.filter(p->p.getFileName().toString().startsWith("original.")).toList())Files.copy(file,home.resolve(file.getFileName()));}var warnings=new ArrayList<String>();SmrWorkflowAudit.analysis(home,a,population,r,b,warnings);Files.writeString(home.resolve("WARNINGS.txt"),String.join("\\n",warnings)+"\\n");}System.out.println("PASS4 complete original overlap tables and active-entry family contract "+r.version());}}
''',encoding='utf8',newline='\n');classes=out/'classes';classes.mkdir();command=[str(JAVA21/'javac.exe'),'--release','17','-Xlint:all','-Werror','-encoding','UTF-8','-cp',str(jar),'-d',str(classes),str(runner)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(out/'compile.stdout').write_bytes(r.stdout);(out/'compile.stderr').write_bytes(r.stderr);assert r.returncode==0,r.stderr.decode(errors='replace');reports=[]
    for version in ['1.3.1','1.4.3']:
        old=base/'workflow-edge-probe-2'/(version+'-overlap');home=out/version;home.mkdir();originals={f.relative_to(old).as_posix():pin(f) for f in old.rglob('*') if f.is_file()};command=[str(JAVA21/'java.exe'),'-Xmx2g','-cp',os.pathsep.join(map(str,[classes,jar])),'org.jlinalg.cli.SmrOverlapContract',str(old),str(home)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(home/'stdout').write_bytes(r.stdout);(home/'stderr').write_bytes(r.stderr);save(home/'process.json',dict(command=command,exit_code=r.returncode));assert all(pin(old/n)==v for n,v in originals.items());reports.append(dict(version=version,exit_code=r.returncode,original_attempt=dict(path=old.relative_to(ROOT).as_posix(),files=originals),tables=4));print(version,'exit',r.returncode,flush=True)
    assert all(pin(ROOT/n)==v for n,v in pins.items());passed=all(r['exit_code']==0 for r in reports);save(out/'COMPLETED.json',dict(status='passed-complete-original-overlap-tables-under-active-entry-contract' if passed else 'FAIL2_OVERLAP_CONTRACT_MISMATCH',artifact=build['artifact'],source_pins=pins,versions=reports,native_original_table_comparisons=8,original_models_reexecuted=False,earlier_failed_batch_reclassified_as_admitted=False,adapter_admitted=False,implementation_credit=False,whole_goal_complete=False));return 0 if passed else 2


